{
  "findings": [
    {
      "check_id": "CKV_AWS_123",
      "title": "SSM Document shared with specific accounts",
      "resource": "aws_ssm_document.pass2",
      "severity": "HIGH",
      "explanation": "The SSM Document is shared with a specific account (680235478471). Sharing sensitive documents can lead to unauthorized access if the account is compromised or not trusted. It is recommended to avoid sharing unless absolutely necessary."
    }
  ],
  "patched_code": "resource "aws_ssm_document" "pass2" {
  name          = "test_document"
  document_type = "Command"

  content = <<DOC
  {
    "schemaVersion": "1.2",
    "description": "Check ip configuration of a Linux instance.",
    "parameters": {

    },
    "runtimeConfig": {
      "aws:runShellScript": {
        "properties": [
          {
            "id": "0.aws:runShellScript",
            "runCommand": ["ifconfig"]
          }
        ]
      }
    }
  }
DOC
  # Removed permissions block to prevent sharing with specific accounts
}
",
  "fix_summary": "Removed the 'permissions' block to prevent sharing the SSM Document with a specific account, reducing the risk of unauthorized access."
}
